    filter: function filter(item) {
      // 1离床 2体动 4睡眠 7打鼾 5在床
      if (item.status == 1) {
        return "#FEDB65";
      } else if (item.status == 2) {
        return "#4DECB9";
      } else if (item.status == 4) {
        return "#FE8565";
      } else if (item.status == 7) {
        return "#A665FE";
      } else if (item.status == 0) {
        return "gray";
      } else {
        return "#2889FE";
      }
    }
